 const [activities,setActivities]=useState(initialActivities),[note,setNote]=useState(''),[deadlines,setDeadlines]=useState({}),[flowReady,setFlowReady]=useState(false),[flowError,setFlowError]=useState(''),[handoff,setHandoff]=useState(false),[postSale,setPostSale]=useState({}),[assignedOwner,setAssignedOwner]=useState(''),[deliveryConfirmed,setDeliveryConfirmed]=useState(false),[taskExpanded,setTaskExpanded]=useState(false),[prospectType,setProspectType]=useState('WhatsApp'),[taskComment,setTaskComment]=useState(''),[taskComments,setTaskComments]=useState([]);
 const [returnWait,setReturnWait]=useState(null),[taskStatuses,setTaskStatuses]=useState({}),[flowEvents,setFlowEvents]=useState([]),[waitDialog,setWaitDialog]=useState(false);
 const [existingClient,setExistingClient]=useState(null);
 const waiting=stage===3;
 const waitLabel=waiting?(returnWait?'Aguardando retorno do cliente até '+new Date(returnWait.until).toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'}):'Definir prazo de retorno do cliente'):'';
 const current=waiting?[waitLabel,'Laura']:stages[stage], progress=Math.round(stage/(stages.length-1)*100), currentOwner=assignedOwner||current[1];
