 useEffect(()=>{try{localStorage.setItem('axivel.navigation',JSON.stringify({view,selectedTask:view==='tasks'?selectedTask:null,selectedCompanyId:view==='company'?selectedCompanyId:''}))}catch{}},[view,selectedTask,selectedCompanyId]);
