 useEffect(()=>{fetch('/api/crm/client/CLI-0001/activities').then(r=>r.json()).then(items=>{if(items.length)setActivities(items)}).catch(()=>{});fetch('/api/crm/client/CLI-0001/post-sale').then(r=>r.json()).then(items=>{if(items.d7)setPostSale(items)}).catch(()=>{});},[]);
 function applyFlow(data){setTaskComments((data.comments||[]).filter(c=>c.stage===data.stage));setProspectType(data.prospectTypes?.[data.stage]||(data.stage===3?data.prospectTypes?.[2]:null)||'WhatsApp');setExistingClient(data.existingClient??null);setStage(data.stage);setDeadlines(data.deadlines);setAssignedOwner(data.assignedOwner||'');setReturnWait(data.returnWait||null);setTaskStatuses(data.taskStatuses||{});setFlowEvents((data.events||[]).map(event=>({...event,stage:event.stage??(event.type==='Comentário da tarefa'?(data.comments||[]).find(comment=>comment.text===event.result&&comment.owner===event.owner&&comment.date===event.date)?.stage:undefined)})));setFlowReady(true);setFlowError('')}
 useEffect(()=>{let active=true;async function sync(){try{const r=await fetch('/api/crm/client/CLI-0001/tasks',{cache:'no-store'});if(!r.ok)throw new Error();const data=await r.json();if(active)applyFlow(data)}catch{if(active)setFlowError('Não foi possível atualizar os prazos. Verifique a conexão com o servidor.')}}sync();const timer=setInterval(sync,2000);return()=>{active=false;clearInterval(timer)}},[]);
