function CompanyProspectTask({company,task,onSaved,onBack}){
 const [flow,setFlow]=useState(company.flow||null),[selected,setSelected]=useState(task.etapa),[busy,setBusy]=useState(false),[error,setError]=useState(''),[comment,setComment]=useState(''),[dialog,setDialog]=useState(false);
 const companyTasks=state=>stages.map(([label,owner],i)=>({id:i,etapa:i,label:i===3&&state.stage===3&&state.returnWait?'Aguardando retorno do cliente até '+new Date(state.returnWait.until).toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'}):label,owner:i===state.stage?(state.assignedOwner||owner):owner,status:state.taskStatuses[i]||(i===state.stage?(i===3?'Aguardando retorno':'Em andamento'):i<state.stage?'Concluído':'Pendente'),due:state.deadlines[i]||'',observacoes:''}));
 function apply(data){setFlow(data);onSaved({...company,flow:data,tarefas:companyTasks(data)})}
 useEffect(()=>{let active=true;async function sync(){try{const response=await fetch('/api/crm/prospects/'+encodeURIComponent(company.id)+'/tasks',{cache:'no-store'});const data=await response.json();if(!response.ok)throw new Error(data.error||'Não foi possível carregar a tarefa.');if(active){setFlow(data);setError('')}}catch(error){if(active)setError(error.message)}}sync();const timer=setInterval(sync,5000);return()=>{active=false;clearInterval(timer)}},[company.id]);
 async function update(input,follow=false){if(busy)return false;setBusy(true);setError('');try{const response=await fetch('/api/crm/prospects/'+encodeURIComponent(company.id)+'/tasks',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});const data=await response.json();if(!response.ok)throw new Error(data.error||'Não foi possível salvar a tarefa.');apply(data);if(follow)setSelected(data.stage);return true}catch(error){setError(error.message);return false}finally{setBusy(false)}}
 if(!flow)return <section className="panel"><button className="text-btn" onClick={onBack}>← Voltar ao cadastro da empresa</button><p role={error?'alert':'status'}>{error||'Carregando tarefa…'}</p></section>;
 const tasks=companyTasks(flow),stage=flow.stage,owner=flow.assignedOwner||stages[stage][1],waiting=stage===3;
 async function advance(){if(stage===2||(waiting&&!flow.returnWait)){setDialog(true);return}await update({action:waiting?'recordResponse':'advance',stage},true)}
 return <div className="company-record"><button className="text-btn company-back" onClick={onBack}>← Voltar ao cadastro da empresa</button>{error&&<p role="alert" className="company-edit-error">{error}</p>}<Tasks key={selected} companyName={company.nome} companyCode={company.id} history={flow.events||[]} tasks={[tasks[selected]]} initialExpanded={true} readOnly={selected!==stage} nextTask={selected!==stage&&tasks[selected].status==='Concluído'?tasks[stage]:null} openNextTask={setSelected} flowReady={!busy} waiting={waiting} hasWait={!!flow.returnWait} currentOwner={owner} qualification={null} saveDeadline={(id,due)=>update({action:'deadline',id,due},true)} advance={advance} passTo={name=>update({action:'assign',stage,owner:name})} prospectType={flow.prospectTypes[stage]||(waiting?flow.prospectTypes[2]:null)||'WhatsApp'} setProspectType={value=>update({action:'prospectType',stage,value})} taskComment={comment} setTaskComment={setComment} taskComments={flow.comments||[]} addTaskComment={async e=>{e.preventDefault();if(await update({action:'comment',stage,text:comment,owner}))setComment('')}}/>{dialog&&<ReturnWaitDialog onCancel={()=>setDialog(false)} onSave={async date=>{const ok=await update({action:'completeContact',stage,date},true);if(ok)setDialog(false);return ok}}/>}</div>;
}

