function ReturnWaitDialog({onCancel,onSave}){
 const [date,setDate]=useState(''),[saving,setSaving]=useState(false),[error,setError]=useState('');
 const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo'}).format(new Date());
 const dialog=React.useRef(null);
 useEffect(()=>{dialog.current.showModal()},[]);
 async function submit(e){e.preventDefault();setSaving(true);setError('');if(!await onSave(date)){setSaving(false);setError('Não foi possível confirmar. Confira a data e a mensagem exibida na página.')}}
 return <dialog ref={dialog} className="return-dialog" aria-labelledby="return-title" onCancel={e=>{e.preventDefault();if(!saving)onCancel()}}><form onSubmit={submit}><div className="section-label">PRIMEIRO CONTATO</div><h2 id="return-title">Aguardar retorno do cliente</h2><p>Até quando Laura deve aguardar a resposta? A próxima ação será liberada ao final do dia escolhido, caso não haja retorno.</p><label>Data limite de retorno<input autoFocus type="date" value={date} min={today} required disabled={saving} onChange={e=>setDate(e.target.value)}/></label>{error&&<p role="alert">{error}</p>}<div className="return-dialog-actions"><button className="secondary" type="button" disabled={saving} onClick={onCancel}>Cancelar</button><button className="primary" disabled={saving}>{saving?'Salvando…':'Concluir contato e aguardar'}</button></div></form></dialog>
}
function ClientQualification({stage,existingClient,onSave}){
 const [value,setValue]=useState(existingClient===null?'':existingClient?'yes':'no'),[saving,setSaving]=useState(false),[message,setMessage]=useState('');
 useEffect(()=>{setValue(existingClient===null?'':existingClient?'yes':'no')},[existingClient]);
 if(stage>4||existingClient!==null)return null;
 async function submit(e){e.preventDefault();setSaving(true);const ok=await onSave({action:'qualifyClient',stage,existingClient:value==='yes'});setSaving(false);setMessage(ok?'Resposta registrada no histórico.':'Não foi possível salvar a resposta.')}
 return <form className="client-qualification" onSubmit={submit}><div className="section-label">QUESTIONAMENTOS DA LAURA</div><p>Confira a empresa na lista de clientes recebida antes de responder.</p><label>A empresa já é cliente da Axivel?<select required value={value} disabled={saving} onChange={e=>{setValue(e.target.value);setMessage('')}}><option value="">Selecione uma resposta</option><option value="yes">Sim, já é cliente</option><option value="no">Não, ainda não é cliente</option></select></label><button className="secondary" disabled={saving||!value}>{saving?'Salvando…':'Salvar resposta'}</button>{message&&<p role="status">{message}</p>}</form>
}
function TaskDeadline({task,editable,onSave}){
 function localValue(iso){if(!iso)return '';const d=new Date(iso);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)}
 const [value,setValue]=useState(()=>localValue(task.due)),[saving,setSaving]=useState(false),[message,setMessage]=useState('');
 useEffect(()=>{setValue(localValue(task.due));setMessage('')},[task.id,task.due]);
 async function save(e){e.preventDefault();setSaving(true);const ok=await onSave(task.id,value?new Date(value+'T23:59:59.999').toISOString():'');setSaving(false);setMessage(ok?'Prazo salvo.':'Prazo não salvo.')}
 return <form className="task-deadline" onSubmit={save}><label>Prazo para ativar a próxima etapa<input aria-label={'Prazo de '+task.label} type="date" value={value} disabled={!editable||saving} onChange={e=>{setValue(e.target.value);setMessage('')}} required/></label>{editable&&<button className="text-btn" disabled={saving}>{saving?'Salvando…':'Salvar prazo'}</button>}{task.due&&<small>Prazo salvo: {new Date(task.due).toLocaleDateString('pt-BR')}</small>}{message&&<small role="status">{message}</small>}</form>
}
function Tasks({companyName="F4 Acessórios",companyCode="CLI-0001",history=[],nextTask,openNextTask,qualification,tasks,waiting=false,hasWait=false,initialExpanded=false,readOnly=false,owner,status,setOwner,setStatus,saveDeadline,flowReady,currentOwner,nextPerson,passTo,advance,prospectType:kind,setProspectType:setKind,taskComment:comment,setTaskComment:setComment,taskComments:comments,addTaskComment:save}){const [open,setOpen]=useState(initialExpanded);return <section className="panel full-panel"><div className="panel-head"><div><div className="section-label">EQUIPE COMERCIAL</div><h3>{initialExpanded?'Detalhes da tarefa':'Minha próxima tarefa'}</h3><p className="muted">Cliente: {companyName} · {companyCode}</p></div></div><p className="muted deadline-help">{waiting?'Aguarde o retorno ou registre uma resposta recebida.':tasks[0]?.id===1?'Escolha o tipo de prospecção e conclua a preparação para abrir o primeiro contato.':tasks[0]?.id===2?'Ao concluir o contato, escolha a data limite para aguardar a resposta.':'Conclua a tarefa para avançar para a próxima etapa.'} {[2,3].includes(tasks[0]?.id)&&(isLocalServer?'O servidor local precisa estar em execução.':'Os prazos são verificados automaticamente.')}</p>{!readOnly&&qualification}<div className="task-list">{tasks.map(t=><div className={'task-row '+taskStateClass(t.status)} key={t.id}><span className="task-icon">→</span><div className="task-info"><strong>{t.label}</strong><small>{companyName} · {companyCode}</small><small>{t.owner} · {t.status}</small></div>{t.id===stages.length-1&&<small>Última etapa do funil</small>}<button className="text-btn" aria-expanded={open} aria-controls={waiting&&!readOnly?'task-waiting-details':undefined} onClick={()=>setOpen(!open)}>{open?'Recolher':'Abrir detalhes'}</button>{!readOnly&&<button className="text-btn" onClick={advance} disabled={!flowReady}>{waiting?(hasWait?'Registrar resposta do cliente':'Definir prazo de retorno'):'Concluir'}</button>}</div>)}</div>{open&&waiting&&!readOnly&&<section id="task-waiting-details" className="task-details" aria-label="Detalhes da espera pelo cliente"><strong>{tasks[0]?.label}</strong><p className="muted">Responsável: {tasks[0]?.owner}</p><p><strong>Tipo de prospecção:</strong> {kind}</p><p className="muted">Registre a resposta quando o cliente retornar. Se o prazo terminar sem resposta, Laura volta a preparar a abordagem por outro meio de contato.</p></section>}{open&&readOnly&&<div className="task-details"><strong>{tasks[0]?.label}</strong><p className="muted">{tasks[0]?.owner} · {tasks[0]?.status}</p></div>}{nextTask&&<div className="handoff-box"><div><div className="section-label">PRÓXIMA ETAPA DISPONÍVEL</div><strong>{nextTask.label}</strong><small>Responsável: {nextTask.owner} · {nextTask.status}</small></div><button className="primary" disabled={!flowReady} onClick={()=>openNextTask(nextTask.id)}>Abrir próxima etapa →</button></div>}{open&&!readOnly&&!waiting&&<div className="task-details"><div className="task-tabs"><strong>{tasks[0]?.label}</strong><label>Tipo de prospecção<select value={kind} disabled={!flowReady} onChange={e=>setKind(e.target.value)}><option>WhatsApp</option><option>Instagram</option><option>Ligação telefônica</option><option>E-mail</option><option>Visita presencial</option></select></label><div className="assign-buttons"><span>Atribuir para</span><button type="button" className="assign-btn" onClick={()=>passTo("Laura")}>Laura</button><button type="button" className="assign-btn" onClick={()=>passTo("Samanta")}>Samanta</button><button type="button" className="assign-btn" onClick={()=>passTo("Ronaldo")}>Ronaldo</button></div></div><form className="note-form" onSubmit={save}><input value={comment} onChange={e=>setComment(e.target.value)} placeholder="Adicionar comentário..."/><button className="primary" disabled={!flowReady}>Registrar comentário</button></form></div>}{open&&history.length>0&&<section className="task-comment-history" aria-label="Histórico da prospecção"><div className="section-label">HISTÓRICO DA PROSPECÇÃO</div><ActivityList activities={history}/></section>}</section>}function Funnel({tasks,stage,openTask,advance,currentOwner,nextPerson,handoff,passTo,waiting,hasWait}){return <section className="panel full-panel"><div className="panel-head"><div><div className="section-label">JORNADA COMPLETA</div><h3>Funil com responsáveis</h3></div><button className="secondary" onClick={advance}>{waiting?(hasWait?'Registrar resposta do cliente':'Definir prazo de retorno'):'Concluir etapa atual'}</button></div><div className="large-steps">{tasks.map((t,i)=><button key={t.id} className={'large-step '+taskStateClass(t.status)+' '+(t.status==='Concluído'?'done ':i===stage?'current ':'')} onClick={()=>openTask(t.id)}><span>{t.status==='Concluído'?'✓':i+1}</span><div><strong>{t.label}</strong><small>{t.owner} · {t.status}</small></div></button>)}</div>{!waiting&&<div className="handoff-box compact"><div><strong>Responsável atual: {currentOwner}</strong><small>{handoff?'Transferência registrada no histórico.':'A passagem deve ser registrada a cada mudança de equipe.'}</small></div><button className="secondary" onClick={()=>passTo(nextPerson)}>Registrar passagem</button></div>}</section>}
function PostSale({stage,deliveryConfirmed,setDeliveryConfirmed,postSale,createPostSale,setPostSale}){const labels=[['d7','7 dias'],['d30','30 dias'],['d90','90 dias']];const saleClosed=stage>=11;return <section className="panel full-panel"><div className="panel-head"><div><div className="section-label">RELACIONAMENTO</div><h3>Pós-venda e satisfação</h3><p className="muted">Samanta acompanha a experiência após a entrega.</p></div>{saleClosed&&!deliveryConfirmed&&<button className="secondary" onClick={()=>setDeliveryConfirmed(true)}>Confirmar entrega</button>}{saleClosed&&deliveryConfirmed&&!postSale.d7&&<button className="primary" onClick={createPostSale}>Criar acompanhamentos</button>}</div>{!saleClosed?<div className="empty-state"><div className="empty-icon">♡</div><h4>Pós-venda ainda não liberado</h4><p>As tarefas serão criadas somente depois que Ronaldo registrar a venda fechada.</p></div>:!deliveryConfirmed?<div className="empty-state"><div className="empty-icon">□</div><h4>Aguardando entrega</h4><p>A venda foi fechada. Confirme a entrega para liberar os contatos de satisfação.</p></div>:postSale.d7?<div className="post-grid">{labels.map(([key,label])=><div className={'post-card '+taskStateClass(postSale[key])+' '+(postSale[key]==='Concluído'?'post-done':'')} key={key}><span>CONTATO</span><strong>Após {label}</strong><small>Responsável: Samanta</small><select value={postSale[key]} onChange={e=>setPostSale({...postSale,[key]:e.target.value})}><option>Pendente</option><option>Concluído</option><option>Requer atenção</option></select><textarea placeholder="Observação da satisfação..."/></div>)}</div>:<div className="empty-state"><div className="empty-icon">♡</div><h4>Entrega confirmada</h4><p>Crie os três acompanhamentos de satisfação para Samanta.</p></div>}<div className="post-note">O registro é manual: anote como o cliente foi atendido, problemas, solução, reposição e próximo contato.</div></section>}
function activityTimestamp(activity){
 const created=Date.parse(activity.createdAt);if(Number.isFinite(created))return created;
 const date=String(activity.date||'');const parts=date.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
 if(parts)return Date.UTC(Number(parts[3]),Number(parts[2])-1,Number(parts[1]));
 if(['Hoje','Agora'].includes(date))return Date.now();
 const parsed=Date.parse(date);return Number.isFinite(parsed)?parsed:0;
}
function activityDateLabel(activity){const date=new Date(activity.createdAt);return Number.isFinite(date.getTime())?date.toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'})+' · '+date.toLocaleTimeString('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit'}):activity.date;}
function activityStage(activity){
 if(Number.isInteger(activity.stage)&&activity.stage>=0&&activity.stage<stages.length)return activity.stage;
 if(activity.type==='Etapa concluída'){const index=stages.findIndex(stage=>stage[0]===activity.result);if(index>=0)return index;}
 if(activity.type==='Aguardando retorno do cliente')return 2;
 if(['Resposta recebida','Prazo encerrado sem retorno'].includes(activity.type))return 3;
 return null;
}
function ActivityList({activities}){
 const groups=new Map();
 for(const activity of [...activities].sort((a,b)=>activityTimestamp(b)-activityTimestamp(a))){
  const stage=activityStage(activity);const key=stage===null?'other':stage;
  if(!groups.has(key))groups.set(key,[]);groups.get(key).push(activity);
 }
 return <div className="activity-stage-list">{[...groups].map(([stage,items])=><section className="activity-stage-group" key={stage}><h4>{stage==='other'?'Outros registros':<><span className="activity-stage-number">ETAPA {String(stage+1).padStart(2,'0')}</span><span>{stages[stage][0]}</span></>}</h4><div className="activity-list">{items.map((a,i)=><div className="activity" key={i}><div className="activity-dot"/><div><div className="activity-top"><time className="activity-date" dateTime={a.createdAt||undefined}>{activityDateLabel(a)}</time><strong>{a.type}</strong><b>{a.owner}</b></div><p>{a.result}</p>{a.prospectType&&<p><strong>Tipo de prospecção:</strong> {a.prospectType}</p>}<small>Próximo: {a.next}</small></div></div>)}</div></section>)}</div>;
}
function History({activities,note,setNote,addActivity}){return <section className="panel full-panel"><div className="panel-head"><div><div className="section-label">LINHA DO TEMPO</div><h3>Histórico de atividades e transferências</h3></div></div><ActivityList activities={activities}/><form className="note-form" onSubmit={addActivity}><input value={note} onChange={e=>setNote(e.target.value)} placeholder="Registrar observação ou resultado..."/><button className="primary">Adicionar nota</button></form></section>}
ReactDOM.createRoot(document.getElementById('root')).render(<App/>);
